insert into public.confirmations (id, position, title, plain_why)
select id, position, title, plain_why from jsonb_populate_recordset(null::public.confirmations, $j$[{"id":"CONFIRM-01","position":1,"title":"Remove XInput2 Second Cursor (XIAddMaster) on :0","plain_why":"Creating a second master cursor on X11 :0 breaks GTK3/GTK4/Qt6 menus and steals keyboard focus. Concurrent multi-cursor GUI work now runs inside isolated Environment B (Xpra/Xvfb/Weston), while host :0 stays single-cursor with a 350 ms typing yield."},{"id":"CONFIRM-02","position":2,"title":"Consolidate Into Single-Relational SQLite WAL (authoritative_audit.db)","plain_why":"SQLite cannot enforce FOREIGN KEY constraints or atomic commits across two separate database files. All relational tables and vector_outbox live in authoritative_audit.db, toggling PRAGMA synchronous = FULL on approvals and NORMAL on streaming chunks."},{"id":"CONFIRM-03","position":3,"title":"Deduplicate & Expand Master Validation Suite to ~650 Atomic Scenarios","plain_why":"Eliminates the 30 duplicate scenarios between 00.D2 and 01.D, splits compound tests (T02-S178, T02-S180), and expands prose summaries into individual Given/When/Then rows."},{"id":"CONFIRM-04","position":4,"title":"Expand ForgeHub Store from 22 to 25 Free On-Demand Packs","plain_why":"Adds Pack 23 (CLI-Anything Desktop JSON Harnesses), Pack 24 (OpenCodeReview + AgentShield DevSecOps), and Pack 25 (Hardware NPU / DirectML / QNN Accelerator) with 0 MB added to the base installer."},{"id":"CONFIRM-05","position":5,"title":"Declarative A2UI v0.9 JSON Contract for .gmod.ts UI Mods","plain_why":"Prohibits raw DOM/HTML injection in UI Mods. Every .gmod.ts runs inside a <4 MB Wasmtime QuickJS-WASM guest and emits declarative A2UI v0.9 JSON rendered safely by React 19."},{"id":"CONFIRM-06","position":6,"title":"Paperclip Org-Swarm & Zero-Token SQLite Pre-Wake Gate","plain_why":"Adopts Paperclip's Org-Chart, Goal-Ancestry, and Atomic 409 Checkout in SQLite, while checking has_actionable_work() in <0.1 ms in Rust so idle heartbeats burn 0 LLM tokens (fixing paperclip#3401)."},{"id":"CONFIRM-07","position":7,"title":"JetBrains Junie-Lite Two-Speed Routing & .junie/AGENTS.md Loader","plain_why":"Routes routine mechanical edits, test scaffolds, and lint fixes to free/local Qwen 3.6/3.5 workhorse models while reserving frontier credits for architecture turns, and auto-deduplicates .forge/AGENTS.md and .junie/AGENTS.md."},{"id":"CONFIRM-08","position":8,"title":"Scope iced.rs Strictly to the <2 ms Native Emergency HUD","plain_why":"Because iced_webview backends either lack CSS Grid/JS (litehtml/Blitz) or bundle 250 MB of Chromium anyway (CEF), Sandboxed Electron + React 19 (and geminiforge-lite) remains the main shell while iced.rs powers the <2 ms Super+Escape kill-switch overlay."}]$j$::jsonb);
